      /* 2.8–5.8 s：窗口从第 0 个 code 扫到第 41 个；6 s 起停在第 8 个（下标 7），在视频里按真实时间轻轻呼吸 */
      var j;
      if (t < 6.0) j = Math.min(CLIP_CODES - 1, Math.floor(ease(seg(t, 2.8, 5.8)) * CLIP_CODES));
