      nFrames.textContent = Math.round(CLIP_FRAMES * gs) + ' 步';
      nCodes.setAttribute('x', (500 + 210 * (CLIP_CODES / CLIP_FRAMES) * gs + 6).toFixed(1));
      nCodes.textContent = Math.round(CLIP_CODES * gs) + ' 步';
      setOpacity(ablG, seg(t, 14.6, 15.0));
