    sG.appendChild(paint(svgText(606, 158, '句向量 s', null, 10), C_WARN)).style.fontWeight = 700;
    sG.appendChild(svgText(606, 172, S7_FEAT + ' 维', 'demo-x-mut', 8.5));
    /* 补充材料图 2(a) 的缩略图：supp_encoders.webp 左边的 405 × 587（文本编码器那一半） */
    var thumb = group(s);
