    fLab.appendChild(svgRich(262, 230, '键 $K$、值 $V$ ← 每个词的特征 · $\\sqrt{' + DIM_ATT + '} \\approx ' + fmt(SQRT_ATT, 1) + '$', { size: 10, w: 380, cls: 'demo-x-ink2' }));

