      var lp = loopFrame(now - 9, S7_SPEED);
      var f = lp.f, pose = clipPose(f), root = pose[0];
      sk.put(pose, { yaw: 0.35, pitch: 0.14, s: 54, ox: 97, oy: 398, cx: root[0], cz: root[2] });
      sk.g.style.opacity = lp.fade;
      var ts = f / UNIT + 1, k0 = Math.min(Math.floor(ts), CLIP_CODES), k1 = Math.min(k0 + 1, CLIP_CODES);
